import"./chunk-VC46IEJQ.js";var e=(a,s,o,r,n)=>({name:a,desc:s,tour:o,source:r,...n?{spoiler:n}:{}}),t={id:"lys",intro:{en:"Lys the Lovely: a warm island city of palms and fruit trees, once a pleasure retreat of the Valyrian dragonlords, whose pale-haired, violet-eyed look still marks many Lysene. It is famed for beauty, pillow houses and poisons, and honours trade above arms.",zh:"\u201C\u7F8E\u4E3D\u7684\u91CC\u65AF\u201D\u662F\u4E00\u5EA7\u6E29\u6696\u7684\u5C9B\u57CE\uFF0C\u68D5\u6988\u4E0E\u679C\u6811\u904D\u5730\uFF0C\u6614\u65E5\u662F\u74E6\u96F7\u5229\u4E9A\u9F99\u738B\u7684\u6E38\u4E50\u4E4B\u5730\uFF1B\u8BB8\u591A\u91CC\u65AF\u4EBA\u81F3\u4ECA\u4ECD\u662F\u6DE1\u53D1\u7D2B\u7738\u7684\u74E6\u96F7\u5229\u4E9A\u76F8\u8C8C\u3002\u8FD9\u5EA7\u57CE\u4EE5\u7F8E\u8272\u3001\u6B22\u6109\u9986\u4E0E\u6BD2\u836F\u95FB\u540D\uFF0C\u91CD\u5546\u800C\u8F7B\u6B66\u3002"},notes:{en:"From the novels: Valyrian looks, pillow houses, the poison called the tears of Lys, Lysene sellswords and the galleys of a Lysene pirate-captain. From TWOIAF and wiki summaries: a fertile island with palms and fruit trees, high walls and hired swords, pleasure gardens, a Temple of Trade and a red temple among many shrines, rule by wealthy magisters. Invented here: the island shape, the cove, every building and its position, and the pastel colours. Slavery is part of Lys in the books; the scene does not depict it.",zh:"\u51FA\u81EA\u5C0F\u8BF4\uFF1A\u74E6\u96F7\u5229\u4E9A\u76F8\u8C8C\u3001\u6B22\u6109\u9986\u3001\u540D\u4E3A\u201C\u91CC\u65AF\u4E4B\u6CEA\u201D\u7684\u6BD2\u836F\u3001\u91CC\u65AF\u4F63\u5175\uFF0C\u4EE5\u53CA\u4E00\u4F4D\u91CC\u65AF\u6D77\u76D7\u8239\u957F\u7684\u6868\u5E06\u8239\u961F\u3002\u51FA\u81EA\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\uFF1A\u4E16\u754C\u300B\u53CA\u7EF4\u57FA\u6458\u8981\uFF1A\u68D5\u6988\u4E0E\u679C\u6811\u7E41\u8302\u7684\u6C83\u5C9B\u3001\u9AD8\u5899\u4E0E\u96C7\u4F63\u5175\u3001\u4EAB\u4E50\u82B1\u56ED\u3001\u4F17\u591A\u795E\u9F9B\u4E2D\u7684\u5546\u4E1A\u795E\u6BBF\u4E0E\u7EA2\u795E\u5E99\uFF0C\u4EE5\u53CA\u5BCC\u6709\u603B\u7763\u7684\u7EDF\u6CBB\u3002\u672C\u573A\u666F\u81EA\u62DF\uFF1A\u5C9B\u5C7F\u5F62\u72B6\u3001\u6D77\u6E7E\u3001\u6240\u6709\u5EFA\u7B51\u53CA\u5176\u4F4D\u7F6E\u3001\u7C89\u5F69\u914D\u8272\u3002\u4E66\u4E2D\u7684\u91CC\u65AF\u6709\u5974\u96B6\u5236\uFF0C\u672C\u573A\u666F\u672A\u4E88\u5448\u73B0\u3002"},tour:["lysene-harbour","galley-yards","perfumers-quarter","pillow-houses","pleasure-gardens","temple-of-trade","magisters-hall","red-temple","city-walls","palm-shore"],sources:[{ref:"acok",checked:"memory",note:{en:"A Lysene pirate-captain and his galleys recalled from memory; no scene re-read.",zh:"\u4E00\u4F4D\u91CC\u65AF\u6D77\u76D7\u8239\u957F\u53CA\u5176\u6868\u5E06\u8239\u961F\uFF0C\u51ED\u8BB0\u5FC6\u590D\u8FF0\uFF1B\u672A\u91CD\u8BFB\u4EFB\u4F55\u7AE0\u8282\u3002"}},{ref:"affc",checked:"memory",note:{en:"Lysene characters, their Valyrian looks and talk of pillow houses recalled from memory; not re-read.",zh:"\u91CC\u65AF\u4EBA\u7269\u3001\u4ED6\u4EEC\u7684\u74E6\u96F7\u5229\u4E9A\u76F8\u8C8C\u4EE5\u53CA\u5173\u4E8E\u6B22\u6109\u9986\u7684\u8C08\u8BBA\uFF0C\u51ED\u8BB0\u5FC6\u590D\u8FF0\uFF1B\u672A\u91CD\u8BFB\u3002"}},{ref:"awoiaf",checked:"search-snippet",note:{en:"Lys the Lovely, palms and fruit trees, walls and hired swords, pillow houses and pleasure gardens, the Temple of Trade, a red temple, poisons, trade held above arms: from web-search summaries (pages not fetched).",zh:"\u201C\u7F8E\u4E3D\u7684\u91CC\u65AF\u201D\u4E4B\u79F0\u3001\u68D5\u6988\u4E0E\u679C\u6811\u3001\u57CE\u5899\u4E0E\u96C7\u4F63\u5175\u3001\u6B22\u6109\u9986\u4E0E\u4EAB\u4E50\u82B1\u56ED\u3001\u5546\u4E1A\u795E\u6BBF\u3001\u7EA2\u795E\u5E99\u3001\u6BD2\u836F\u3001\u91CD\u5546\u8F7B\u6B66\uFF1A\u636E\u7F51\u7EDC\u641C\u7D22\u6458\u8981\uFF08\u672A\u80FD\u6253\u5F00\u9875\u9762\uFF09\u3002"}},{ref:"twoiaf",checked:"search-snippet",note:{en:"Position of Lys and its Valyrian past: search summary only.",zh:"\u91CC\u65AF\u7684\u5730\u7406\u4F4D\u7F6E\u4E0E\u74E6\u96F7\u5229\u4E9A\u6E0A\u6E90\uFF1A\u4EC5\u636E\u641C\u7D22\u6458\u8981\u3002"}}],landmarks:{"lysene-harbour":e({en:"Lysene Harbour",zh:"\u91CC\u65AF\u6E2F"},{en:"A sheltered cove ringed with quays, where galleys with brightly painted hulls ride at anchor.",zh:"\u7801\u5934\u73AF\u62B1\u7684\u907F\u98CE\u6D77\u6E7E\uFF0C\u8239\u8EAB\u6F06\u5F97\u4E94\u989C\u516D\u8272\u7684\u6868\u5E06\u8239\u5728\u6B64\u4E0B\u951A\u3002"},{en:"Lysene galleys are painted in bold stripes and colours.",zh:"\u91CC\u65AF\u7684\u6868\u5E06\u8239\u6F06\u7740\u9192\u76EE\u7684\u6761\u7EB9\u4E0E\u8272\u5F69\u3002"},{confidence:"medium",refs:["acok","awoiaf"],book:{en:"Lys is a major trading port; Lysene galleys appear in the novels, and summaries describe their brightly coloured, often striped hulls.",zh:"\u91CC\u65AF\u662F\u91CD\u8981\u5546\u6E2F\uFF1B\u5C0F\u8BF4\u4E2D\u6709\u91CC\u65AF\u6868\u5E06\u8239\u767B\u573A\uFF0C\u6458\u8981\u79F0\u5176\u8239\u8EAB\u8272\u5F69\u9C9C\u8273\uFF0C\u5E38\u5E26\u6761\u7EB9\u3002"},unknown:{en:"The real harbour shape and defences.",zh:"\u6E2F\u53E3\u7684\u771F\u5B9E\u5F62\u72B6\u4E0E\u9632\u5FA1\u3002"},interpretation:{en:"A round cove open to the west, with quays, piers and two guard towers; single-colour hulls stand in for stripes.",zh:"\u5411\u897F\u5F00\u53E3\u7684\u5706\u5F62\u6D77\u6E7E\uFF0C\u8BBE\u7801\u5934\u3001\u6808\u6865\u4E0E\u4E24\u5EA7\u54E8\u5854\uFF1B\u4EE5\u5355\u8272\u8239\u8EAB\u4EE3\u66FF\u6761\u7EB9\u3002"}}),"city-walls":e({en:"City Walls",zh:"\u57CE\u5899"},{en:"High walls and hired swords guard the city on its landward side.",zh:"\u9AD8\u5899\u4E0E\u96C7\u4F63\u5175\u5B88\u62A4\u7740\u57CE\u5E02\u7684\u9646\u4FA7\u3002"},{en:"Lys trusts walls and sellswords more than its citizens' own blades.",zh:"\u6BD4\u8D77\u81EA\u5BB6\u516C\u6C11\u7684\u5200\u5251\uFF0C\u91CC\u65AF\u66F4\u4FE1\u8D56\u57CE\u5899\u4E0E\u4F63\u5175\u3002"},{confidence:"medium",refs:["twoiaf","awoiaf"],book:{en:"Lys is protected by high walls and hired swords; trade is held more honourable than arms (companion summaries).",zh:"\u91CC\u65AF\u7531\u9AD8\u5899\u4E0E\u96C7\u4F63\u5175\u5B88\u536B\uFF1B\u7ECF\u5546\u88AB\u89C6\u4E3A\u6BD4\u4ECE\u519B\u66F4\u4F53\u9762\uFF08\u636E\u8BBE\u5B9A\u96C6\u6458\u8981\uFF09\u3002"},unknown:{en:"Wall circuit and gates.",zh:"\u57CE\u5899\u8D70\u5411\u4E0E\u57CE\u95E8\u3002"},interpretation:{en:"A pale arc of wall on the landward side, with spire-topped towers and one gate.",zh:"\u9646\u4FA7\u4E00\u9053\u6D45\u8272\u5F27\u5F62\u57CE\u5899\uFF0C\u5854\u9876\u5E26\u5C16\uFF0C\u53EA\u5F00\u4E00\u95E8\u3002"}}),"pillow-houses":e({en:"Pillow Houses",zh:"\u6B22\u6109\u9986"},{en:"Lantern-lit pavilions on the slope: the pleasure houses for which Lys is notorious.",zh:"\u5761\u4E0A\u706F\u7B3C\u9AD8\u60AC\u7684\u4EAD\u9601\uFF0C\u6B63\u662F\u91CC\u65AF\u58F0\u540D\u72FC\u85C9\u7684\u6B22\u573A\u3002"},{en:"Pink lanterns mark the houses that made Lys famous, and infamous.",zh:"\u7C89\u8272\u706F\u7B3C\u6807\u51FA\u4E86\u8BA9\u91CC\u65AF\u65E2\u51FA\u540D\u53C8\u843D\u4E0B\u6076\u540D\u7684\u6B22\u573A\u3002"},{confidence:"high",refs:["affc","adwd","awoiaf"],book:{en:"Lys is known for its pillow houses, whose trade rests largely on slaves.",zh:"\u91CC\u65AF\u4EE5\u6B22\u6109\u9986\u95FB\u540D\uFF0C\u8FD9\u95E8\u8425\u751F\u5927\u591A\u5EFA\u7ACB\u5728\u5974\u96B6\u8EAB\u4E0A\u3002"},unknown:{en:"Where they stand and how they look.",zh:"\u4F4D\u7F6E\u4E0E\u6837\u8C8C\u3002"},interpretation:{en:"Five painted pavilions around a fountain court, hung with lanterns and awnings.",zh:"\u4E94\u5EA7\u5F69\u7ED8\u4EAD\u9601\u56F4\u7740\u55B7\u6CC9\u5EAD\u9662\uFF0C\u6302\u6EE1\u706F\u7B3C\u4E0E\u7BF7\u5E03\u3002"}}),"pleasure-gardens":e({en:"Pleasure Gardens",zh:"\u4EAB\u4E50\u82B1\u56ED"},{en:"Terraced gardens of flowers, palms and fountains laid out for leisure.",zh:"\u4F9B\u4EBA\u6E38\u61A9\u7684\u53F0\u5730\u82B1\u56ED\uFF0C\u7E41\u82B1\u3001\u68D5\u6988\u4E0E\u55B7\u6CC9\u70B9\u7F00\u5176\u95F4\u3002"},{en:"Flowers, pools and fountains: the gentle face of Lys.",zh:"\u7E41\u82B1\u3001\u6C34\u6C60\u4E0E\u55B7\u6CC9\uFF1A\u91CC\u65AF\u6E29\u67D4\u7684\u4E00\u9762\u3002"},{confidence:"medium",refs:["awoiaf"],book:{en:"Pleasure gardens are mentioned alongside the pillow houses; the term also refers to high-class brothels.",zh:"\u4EAB\u4E50\u82B1\u56ED\u4E0E\u6B22\u6109\u9986\u5E38\u88AB\u5E76\u63D0\uFF1B\u8FD9\u4E2A\u8BCD\u672C\u8EAB\u4E5F\u6307\u9AD8\u6863\u5993\u9662\u3002"},unknown:{en:"Layout and planting.",zh:"\u5E03\u5C40\u4E0E\u82B1\u6728\u3002"},interpretation:{en:"Open terraces with coloured flower beds, palms, two pools and fountains.",zh:"\u5F00\u655E\u7684\u53F0\u5730\uFF0C\u8BBE\u5F69\u8272\u82B1\u5703\u3001\u68D5\u6988\u3001\u4E24\u5904\u6C34\u6C60\u4E0E\u55B7\u6CC9\u3002"}}),"perfumers-quarter":e({en:"Perfumers' Quarter",zh:"\u9999\u6C34\u4F5C\u574A\u533A"},{en:"Small domed workshops and awninged shops, with a faint haze of scent drifting from the stills.",zh:"\u5706\u9876\u5C0F\u4F5C\u574A\u4E0E\u642D\u7BF7\u7684\u94FA\u9762\uFF0C\u84B8\u998F\u5668\u91CC\u98D8\u51FA\u6DE1\u6DE1\u9999\u96FE\u3002"},{en:"Scents and subtler distillations: Lysene alchemists are known for their poisons.",zh:"\u9999\u6C34\u4E4B\u5916\u8FD8\u6709\u66F4\u9690\u79D8\u7684\u84B8\u998F\u7269\uFF1A\u91CC\u65AF\u70BC\u91D1\u672F\u58EB\u4EE5\u5236\u6BD2\u95FB\u540D\u3002"},{confidence:"low",refs:["awoiaf"],book:{en:"Lysene alchemists are known for poisons such as the tears of Lys; a perfume trade is assumed, not confirmed.",zh:"\u91CC\u65AF\u70BC\u91D1\u672F\u58EB\u4EE5\u201C\u91CC\u65AF\u4E4B\u6CEA\u201D\u7B49\u6BD2\u836F\u95FB\u540D\uFF1B\u9999\u6C34\u4E1A\u53EA\u662F\u63A8\u6D4B\uFF0C\u672A\u7ECF\u8BC1\u5B9E\u3002"},unknown:{en:"Whether there is any such quarter.",zh:"\u662F\u5426\u771F\u6709\u8FD9\u6837\u7684\u8857\u533A\u3002"},interpretation:{en:"A cluster of workshops with a still-tower in the west of the town.",zh:"\u57CE\u897F\u4E00\u7C07\u4F5C\u574A\uFF0C\u9644\u4E00\u5EA7\u84B8\u998F\u5854\u3002"}}),"temple-of-trade":e({en:"Temple of Trade",zh:"\u5546\u4E1A\u795E\u6BBF"},{en:"A broad colonnaded hall under a golden dome, for a city that honours commerce.",zh:"\u91D1\u8272\u7A79\u9876\u4E0B\u7684\u5BBD\u9614\u67F1\u5ECA\u6BBF\u5802\uFF0C\u5C5E\u4E8E\u8FD9\u5EA7\u5C0A\u5D07\u5546\u4E1A\u7684\u57CE\u90A6\u3002"},{en:"Trade has its own temple here, and its own dome.",zh:"\u5728\u8FD9\u91CC\uFF0C\u5546\u4E1A\u6709\u81EA\u5DF1\u7684\u795E\u6BBF\uFF0C\u4E5F\u6709\u81EA\u5DF1\u7684\u7A79\u9876\u3002"},{confidence:"medium",refs:["twoiaf","awoiaf"],book:{en:"Summaries list a Temple of Trade among the many temples and shrines of Lys.",zh:"\u636E\u6458\u8981\uFF0C\u5546\u4E1A\u795E\u6BBF\u662F\u91CC\u65AF\u4F17\u591A\u795E\u6BBF\u4E0E\u795E\u9F9B\u4E4B\u4E00\u3002"},unknown:{en:"Its form and position.",zh:"\u5F62\u5236\u4E0E\u4F4D\u7F6E\u3002"},interpretation:{en:"A broad marble hall with a colonnade and golden dome.",zh:"\u5E26\u67F1\u5ECA\u4E0E\u91D1\u9876\u7684\u5BBD\u5927\u7406\u77F3\u6BBF\u5802\u3002"}}),"red-temple":e({en:"Red Temple",zh:"\u7EA2\u795E\u5E99"},{en:"A stepped red temple of the Lord of Light among the white buildings.",zh:"\u767D\u8272\u5EFA\u7B51\u7FA4\u4E2D\uFF0C\u4E00\u5EA7\u5C42\u5C42\u6536\u8FDB\u7684\u5149\u4E4B\u738B\u7EA2\u795E\u5E99\u3002"},{en:"A flash of red in a white city: the temple of R'hllor.",zh:"\u767D\u57CE\u4E2D\u7684\u4E00\u62B9\u7EA2\uFF1A\u62C9\u8D6B\u6D1B\u7684\u795E\u5E99\u3002"},{confidence:"low",refs:["twoiaf","awoiaf"],book:{en:"Summaries list a red temple of R'hllor among the shrines of Lys.",zh:"\u636E\u6458\u8981\uFF0C\u91CC\u65AF\u7684\u795E\u9F9B\u4E2D\u6709\u4E00\u5EA7\u62C9\u8D6B\u6D1B\u7EA2\u795E\u5E99\u3002"},unknown:{en:"Everything about its architecture.",zh:"\u5EFA\u7B51\u5F62\u5236\u4E00\u6982\u4E0D\u660E\u3002"},interpretation:{en:"A four-stepped red tower with corner columns; invented.",zh:"\u5E26\u89D2\u67F1\u7684\u56DB\u5C42\u9636\u68AF\u5F0F\u7EA2\u5854\uFF1B\u7CFB\u81EA\u62DF\u3002"}}),"magisters-hall":e({en:"Magisters' Hall",zh:"\u603B\u7763\u8BAE\u4E8B\u5385"},{en:"A pale colonnaded hall with a silver dome and spires, imagined as the seat of the ruling magisters.",zh:"\u94F6\u9876\u5C16\u5854\u7684\u6D45\u8272\u67F1\u5ECA\u5927\u5385\uFF0C\u8BBE\u60F3\u4E3A\u6267\u653F\u603B\u7763\u4EEC\u7684\u8BAE\u4E8B\u4E4B\u6240\u3002"},{en:"Wealth, not lineage alone, rules Lys, and here it sits.",zh:"\u7EDF\u6CBB\u91CC\u65AF\u7684\u4E0D\u53EA\u662F\u8840\u7EDF\uFF0C\u66F4\u662F\u8D22\u5BCC\uFF0C\u800C\u5B83\u5C31\u5750\u9547\u4E8E\u6B64\u3002"},{confidence:"low",refs:["twoiaf","awoiaf"],book:{en:"Lys is governed by wealthy magisters; no hall is described in the sources checked.",zh:"\u91CC\u65AF\u7531\u5BCC\u6709\u7684\u603B\u7763\u6CBB\u7406\uFF1B\u6240\u67E5\u8D44\u6599\u672A\u63CF\u5199\u4EFB\u4F55\u6BBF\u5802\u3002"},unknown:{en:"Whether such a hall exists, and where.",zh:"\u662F\u5426\u6709\u6B64\u6BBF\u5802\uFF0C\u4F4D\u4E8E\u4F55\u5904\u3002"},interpretation:{en:"Entirely invented; placed on the hill north-east of the cove.",zh:"\u7EAF\u5C5E\u81EA\u62DF\uFF1B\u7F6E\u4E8E\u6D77\u6E7E\u4E1C\u5317\u7684\u5C71\u5761\u4E0A\u3002"}}),"palm-shore":e({en:"Palm Shore",zh:"\u68D5\u6988\u6D77\u5CB8"},{en:"Pale beaches and palm groves along the island's southern coast.",zh:"\u5C9B\u5357\u6D77\u5CB8\u7684\u767D\u6C99\u6EE9\u4E0E\u68D5\u6988\u6797\u3002"},{en:"Palms and fruit trees grow thick on this sunny island.",zh:"\u8FD9\u5EA7\u9633\u5149\u5145\u6C9B\u7684\u5C9B\u4E0A\uFF0C\u68D5\u6988\u4E0E\u679C\u6811\u957F\u5F97\u7E41\u8302\u3002"},{confidence:"medium",refs:["twoiaf","awoiaf"],book:{en:"Lys is described as a sunny, fertile island of palms and fruit trees in blue-green, fish-rich waters (companion summaries).",zh:"\u91CC\u65AF\u88AB\u63CF\u8FF0\u4E3A\u9633\u5149\u5145\u8DB3\u7684\u6C83\u5C9B\uFF0C\u68D5\u6988\u4E0E\u679C\u6811\u7E41\u8302\uFF0C\u56DB\u5468\u84DD\u7EFF\u8272\u7684\u6D77\u6C34\u4E2D\u9C7C\u7FA4\u4E30\u5BCC\uFF08\u636E\u8BBE\u5B9A\u96C6\u6458\u8981\uFF09\u3002"},unknown:{en:"Coastline and beaches.",zh:"\u6D77\u5CB8\u7EBF\u4E0E\u6C99\u6EE9\u3002"},interpretation:{en:"A crescent island with sand beaches; palms placed arbitrarily.",zh:"\u5E26\u6C99\u6EE9\u7684\u65B0\u6708\u5F62\u5C9B\u5C7F\uFF1B\u68D5\u6988\u4F4D\u7F6E\u968F\u610F\u3002"}}),"galley-yards":e({en:"Galley Yards",zh:"\u8239\u575E"},{en:"Long sheds on the north shore where galleys are built and refitted.",zh:"\u5317\u5CB8\u7684\u957F\u68DA\uFF0C\u6868\u5E06\u8239\u5728\u6B64\u5EFA\u9020\u4E0E\u4FEE\u6574\u3002"},{en:"Lysene fleets are imagined being built and refitted here.",zh:"\u8BBE\u60F3\u91CC\u65AF\u7684\u8239\u961F\u5728\u6B64\u5EFA\u9020\u4E0E\u4FEE\u6574\u3002"},{confidence:"low",refs:["acok"],book:{en:"Lysene galleys and fleets are established; no shipyard was found in the sources checked.",zh:"\u91CC\u65AF\u7684\u6868\u5E06\u8239\u4E0E\u8239\u961F\u6709\u636E\u53EF\u67E5\uFF1B\u6240\u67E5\u8D44\u6599\u4E2D\u672A\u89C1\u8239\u575E\u3002"},unknown:{en:"Whether and where shipyards stand.",zh:"\u662F\u5426\u6709\u8239\u575E\uFF0C\u4F4D\u4E8E\u4F55\u5904\u3002"},interpretation:{en:"Five sheds on the north shore; invented.",zh:"\u5317\u5CB8\u4E94\u5EA7\u8239\u68DA\uFF1B\u7CFB\u81EA\u62DF\u3002"}})}};export{t as default};
